def strip_for_candidates(html):
    text = re.sub(r"<[^>]+>", " ", html)          # tagek + attribútum-URL-ek eldobása
    text = re.sub(r"https?://\S+", " ", text)      # látható URL-ek
    text = re.sub(r"\b\S+@\S+\b", " ", text)       # email címek
    return text

def camel_parts(c):
    return [w.lower() for w in re.findall(r"[A-Z]+(?![a-z])|[A-Z][a-z0-9]*|[a-z0-9]+", c) if len(w) >= 3]

def norm(s):
    return re.sub(r"[^a-z0-9]", "", s.lower())

def verified(c, hay):
    if c in hay: return True
    nh = norm(hay)
    if norm(c) and norm(c) in nh: return True
    parts = camel_parts(c)
    return bool(parts) and all(p in nh for p in parts)

def extract2(html):
    text = strip_for_candidates(html)
    quoted  = re.findall(r"'([A-Z][A-Za-z0-9 _.:/-]{2,50})'", text)
    dotted  = [d for d in re.findall(r"\b([a-z]+[a-z0-9]*(?:\.[a-z0-9_]+)+)\b", text)
               if any(len(seg) >= 2 for seg in d.split("."))]
    camel   = re.findall(r"\b([A-Z][a-z]+(?:[A-Z][a-z]+)+)\b", text)
    out=[]
    for c in quoted+dotted+camel:
        c=c.strip()
        if c and c not in out: out.append(c)
    return out

